/// The engine version this port reproduces. Replays and `hello` report the server's.
pub const ENGINE_VERSION: &str = "0.23.0";

/// The shipped rules table and maps (ladder release 0.82.2), for tests and benchmarks.
/// A live bot uses the rules and map from `hello` instead.
pub mod shipped {
    pub const RULES_JSON: &str = include_str!("../data/rules.json");
    pub const MAP_NAMES: [&str; 3] = ["arena-21", "columns-21", "pillars-21"];
    pub const MAPS_JSON: [&str; 3] = [
        include_str!("../data/arena-21.json"),
        include_str!("../data/columns-21.json"),
        include_str!("../data/pillars-21.json"),
    ];
}

/// The immutable part of a match: rules and map, with the map's lookup tables.
#[derive(Clone, Debug)]
pub struct Engine {
    pub rules: Rules,
    pub map: MapData,
}

// PCG32 (XSH RR), as in `packages/engine/src/rng.ts`.
const PCG_MULT: u64 = 6364136223846793005;
const PCG_INC: u64 = 1442695040888963407;

fn rng_seed(seed: i64) -> u64 {
    let mut state: u64 = 0;
    state = state.wrapping_mul(PCG_MULT).wrapping_add(PCG_INC);
    state = state.wrapping_add(seed as u64);
    state.wrapping_mul(PCG_MULT).wrapping_add(PCG_INC)
}

fn rng_next(state: &mut u64) -> u32 {
    let old = *state;
    *state = old.wrapping_mul(PCG_MULT).wrapping_add(PCG_INC);
    let xorshifted = (((old >> 18) ^ old) >> 27) as u32;
    let rot = (old >> 59) as u32;
    xorshifted.rotate_right(rot)
}

fn rng_int(state: &mut u64, n: u32) -> u32 {
    let limit = 0x1_0000_0000u64 - (0x1_0000_0000u64 % n as u64);
    loop {
        let v = rng_next(state);
        if (v as u64) < limit {
            return v % n;
        }
    }
}

impl Engine {
    pub fn new(rules: Rules, map: MapData) -> Result<Engine, String> {
        for p in &map.pads {
            let defined = match (p.kind, rules.pickups.as_ref()) {
                (map::PadKind::Health, Some(pr)) => pr.health.is_some(),
                (map::PadKind::Power, Some(pr)) => pr.power.is_some(),
                (_, None) => false,
            };
            if !defined {
                return Err(format!(
                    "match: map {} places a {} pickup the rules don't define",
                    map.name,
                    p.kind.name()
                ));
            }
        }
        Ok(Engine { rules, map })
    }

    pub fn from_json(rules: &serde_json::Value, map: &serde_json::Value) -> Result<Engine, String> {
        Engine::new(Rules::from_json(rules)?, MapData::from_json(map)?)
    }

    /// The shipped rules with one of the shipped maps, by name.
    pub fn shipped(map_name: &str) -> Engine {
        let i = shipped::MAP_NAMES.iter().position(|n| *n == map_name).expect("unknown shipped map");
        let rules: serde_json::Value = serde_json::from_str(shipped::RULES_JSON).unwrap();
        let map: serde_json::Value = serde_json::from_str(shipped::MAPS_JSON[i]).unwrap();
        Engine::from_json(&rules, &map).unwrap()
    }

    /// The state before tick 0. The seed decides which fighter takes which spawn; that
    /// one draw is the only randomness in a match.
    pub fn new_match(&self, seed: i64) -> State {
        let mut rng = rng_seed(seed);
        let swap = rng_int(&mut rng, 2) == 1;
        let spawns = if swap { [self.map.spawns[1], self.map.spawns[0]] } else { [self.map.spawns[0], self.map.spawns[1]] };
        let fighter = |pos: P| Fighter {
            pos,
            hp: self.rules.max_hp,
            state: FState::Idle,
            state_end: 0,
            cd_move: 0,
            cd_dash: 0,
            cd_shout: 0,
            cd_attack: [0; rules::MAX_ATTACKS],
            ticks_outside: 0,
            invulnerable: false,
            alive: true,
            damage_dealt: 0,
            power_until: NO_BUFF,
        };
        let first_spawn = self.rules.pickups.as_ref().map(|p| p.first_spawn).unwrap_or(0);
        State {
            tick: 0,
            fighters: [fighter(spawns[0]), fighter(spawns[1])],
            projectiles: [EMPTY_PROJECTILE; MAX_PROJECTILES],
            n_projectiles: 0,
            areas: [EMPTY_AREA; MAX_AREAS],
            n_areas: 0,
            pads: [Pad { available: false, respawn_tick: first_spawn }; map::MAX_PADS],
            next_projectile_id: 1,
            zone_radius: step::zone_radius_at(&self.rules, &self.map, 0),
            result: None,
            seed,
            rng,
        }
    }

    /// Resolves one tick in place. `turns[0]` is fighter 1's turn, `turns[1]` fighter 2's.
    #[inline]
    pub fn step(&self, s: &mut State, turns: &[RawTurn; 2]) -> TickSummary {
        step::step(&self.rules, &self.map, s, turns)
    }

    /// As `step`, and also records the tick's events in the official order.
    pub fn step_events(&self, s: &mut State, turns: &[RawTurn; 2], events: &mut Vec<events::Event>) -> TickSummary {
        step::step_events(&self.rules, &self.map, s, turns, events)
    }

    /// Canonical JSON of everything that affects the future of the match, exactly as the
    /// official engine writes it before hashing.
    pub fn state_json(&self, s: &State, out: &mut String) {
        out.clear();
        let pt = |out: &mut String, p: P| {
            let _ = write!(out, "[{},{}]", p[0], p[1]);
        };
        out.push_str("{\"areas\":[");
        for (i, b) in s.areas().iter().enumerate() {
            if i > 0 {
                out.push(',');
            }
            let _ = write!(
                out,
                "{{\"attack\":\"{}\",\"damage\":{},\"explodes_tick\":{},\"id\":{},\"launched_tick\":{},\"origin\":",
                self.rules.attacks[b.attack as usize].name, b.damage, b.explodes_tick, b.id, b.launched_tick
            );
            pt(out, b.origin);
            let _ = write!(out, ",\"owner\":{},\"pos\":", b.owner + 1);
            pt(out, b.pos);
            let _ = write!(out, ",\"radius\":{},\"slow\":{}}}", b.radius, b.slow);
        }
        out.push_str("],\"fighters\":[");
        for (i, f) in s.fighters.iter().enumerate() {
            if i > 0 {
                out.push(',');
            }
            let _ = write!(out, "{{\"alive\":{},\"buffs\":{{", f.alive);
            if f.power_until != NO_BUFF {
                let _ = write!(out, "\"power\":{}", f.power_until);
            }
            out.push_str("},\"cooldowns\":{");
            for (k, (name, slot)) in self.rules.cooldown_keys.iter().enumerate() {
                if k > 0 {
                    out.push(',');
                }
                let v = match slot {
                    CdSlot::Move => f.cd_move,
                    CdSlot::Dash => f.cd_dash,
                    CdSlot::Shout => f.cd_shout,
                    CdSlot::Attack(a) => f.cd_attack[*a as usize],
                };
                let _ = write!(out, "\"{name}\":{v}");
            }
            let _ = write!(
                out,
                "}},\"damage_dealt\":{},\"hp\":{},\"id\":{},\"invulnerable\":{},\"pos\":",
                f.damage_dealt,
                f.hp,
                i + 1,
                f.invulnerable
            );
            pt(out, f.pos);
            let _ = write!(
                out,
                ",\"state\":\"{}\",\"state_end\":{},\"team\":{},\"ticks_outside\":{}}}",
                f.state.name(),
                f.state_end,
                i + 1,
                f.ticks_outside
            );
        }
        let _ = write!(out, "],\"next_projectile_id\":{},\"pickups\":[", s.next_projectile_id);
        for (i, def) in self.map.pads.iter().enumerate() {
            if i > 0 {
                out.push(',');
            }
            let pad = &s.pads[i];
            let _ = write!(out, "{{\"available\":{},\"id\":{},\"kind\":\"{}\",\"pos\":", pad.available, i + 1, def.kind.name());
            pt(out, def.pos);
            let _ = write!(out, ",\"respawn_tick\":{}}}", pad.respawn_tick);
        }
        out.push_str("],\"projectiles\":[");
        for (i, p) in s.projectiles().iter().enumerate() {
            if i > 0 {
                out.push(',');
            }
            let _ = write!(
                out,
                "{{\"attack\":\"{}\",\"bounces_left\":{},\"damage\":{},\"exact_pos\":",
                self.rules.attacks[p.attack as usize].name, p.bounces_left, p.damage
            );
            pt(out, p.exact_pos);
            let _ = write!(out, ",\"id\":{},\"max_travel\":{},\"origin\":", p.id, p.max_travel);
            pt(out, p.origin);
            let _ = write!(out, ",\"owner\":{},\"pos\":", p.owner + 1);
            pt(out, p.pos);
            let _ = write!(out, ",\"speed\":{},\"target\":", p.speed);
            pt(out, p.target);
            let _ = write!(out, ",\"traveled\":{}}}", p.traveled);
        }
        out.push_str("],\"result\":");
        match &s.result {
            None => out.push_str("null"),
            Some(r) => {
                let _ = write!(out, "{{\"final_tick\":{},\"reason\":\"{}\",\"winner\":", r.final_tick, r.reason.name());
                match r.winner {
                    None => out.push_str("null"),
                    Some(w) => {
                        let _ = write!(out, "{w}");
                    }
                }
                out.push('}');
            }
        }
        let _ = write!(out, ",\"rng\":{{\"s\":\"{}\"}},\"seed\":{},\"tick\":{},\"zone\":{{\"center\":", s.rng, s.seed, s.tick);
        pt(out, self.map.center);
        let _ = write!(out, ",\"radius\":{}}}}}", s.zone_radius);
    }

    /// The state hash the ladder records for every tick of every replay.
    pub fn state_hash(&self, s: &State) -> String {
        let mut json = String::with_capacity(2048);
        self.state_json(s, &mut json);
        hash::hash_string(&json)
    }
}
